-- Historial sintético académico; reemplaza datos clínicos y pronósticos, conserva cuenta y tareas.
-- Ejecutar completo en Supabase SQL Editor, una sola vez. Respaldo privado dentro de la transacción.
BEGIN;
SET LOCAL standard_conforming_strings = on;
LOCK TABLE public.pacientes, public.atenciones, public.ml_demanda_diaria, public.ml_pronosticos_v2, public.ml_predicciones_demanda IN ACCESS EXCLUSIVE MODE;
CREATE SCHEMA respaldo_historial_20261023;
REVOKE ALL ON SCHEMA respaldo_historial_20261023 FROM PUBLIC, anon, authenticated;
CREATE TABLE respaldo_historial_20261023."ml_pronosticos_v2" AS TABLE public."ml_pronosticos_v2";
CREATE TABLE respaldo_historial_20261023."ml_predicciones_demanda" AS TABLE public."ml_predicciones_demanda";
CREATE TABLE respaldo_historial_20261023."ml_demanda_diaria" AS TABLE public."ml_demanda_diaria";
CREATE TABLE respaldo_historial_20261023."atenciones" AS TABLE public."atenciones";
CREATE TABLE respaldo_historial_20261023."pacientes" AS TABLE public."pacientes";
DELETE FROM public."ml_pronosticos_v2";
DELETE FROM public."ml_predicciones_demanda";
DELETE FROM public."ml_demanda_diaria";
DELETE FROM public."atenciones";
DELETE FROM public."pacientes";
SELECT setval(pg_get_serial_sequence('public.pacientes', 'id'), COALESCE(MAX(id),1), COUNT(*)>0) FROM public."pacientes";
SELECT setval(pg_get_serial_sequence('public.atenciones', 'id'), COALESCE(MAX(id),1), COUNT(*)>0) FROM public."atenciones";
SELECT setval(pg_get_serial_sequence('public.ml_demanda_diaria', 'id'), COALESCE(MAX(id),1), COUNT(*)>0) FROM public."ml_demanda_diaria";
SELECT setval(pg_get_serial_sequence('public.ml_pronosticos_v2', 'id'), COALESCE(MAX(id),1), COUNT(*)>0) FROM public."ml_pronosticos_v2";
DO $$ BEGIN
IF (SELECT COUNT(*) FROM public."pacientes") <> 1000 THEN RAISE EXCEPTION 'Conteo incorrecto: pacientes'; END IF;
IF (SELECT COUNT(*) FROM public."atenciones") <> 9569 THEN RAISE EXCEPTION 'Conteo incorrecto: atenciones'; END IF;
IF (SELECT COUNT(*) FROM public."ml_demanda_diaria") <> 726 THEN RAISE EXCEPTION 'Conteo incorrecto: ml_demanda_diaria'; END IF;
IF (SELECT COUNT(*) FROM public."ml_pronosticos_v2") <> 60 THEN RAISE EXCEPTION 'Conteo incorrecto: ml_pronosticos_v2'; END IF;
IF EXISTS (SELECT 1 FROM public.ml_demanda_diaria d WHERE d.total_atenciones <> (SELECT COUNT(*) FROM public.atenciones a WHERE a.fecha=d.fecha)) THEN RAISE EXCEPTION 'Agregados inconsistentes'; END IF;
END $$;
COMMIT;
